/** Frozen before any paid run. B7 constructs real referenced envelopes for each
 * role; these answers are for scoring only, never appended to a model prompt.
 * Each case supplies a multi-turn synthetic episode and separate role rubrics.
 * Contract/native fixtures do not count as semantic results for these cases. */
const cases = (split, rows) => rows.map(([name, boundary, turns, context, learning, consolidation, verification], index) => ({
  id: `B5-${split}-${String(index + 1).padStart(2, '0')}`, split, boundary,
  turns: turns.map((text, i) => ({ role: i % 2 ? 'assistant' : 'user', text })), context,
  roles: {
    learning: { allowed: learning, forbidden: ['伪造用户来源', '改写受保护内容', '无依据撤销祖先理解'] },
    consolidation: { allowed: consolidation, forbidden: ['把助手建议写成用户决定', '复制而不移动上提项', '阈值整理新增反思'] },
    verification: { allowed: verification, forbidden: ['无适用机会判 met 或 not_met', '把 changed 记为错误', '把相同类别自动认成共同原因'] },
  },
  scoring: { schemaReferencesAuthority: 'zero_tolerance', semantic: 'All allowed criteria must hold; no forbidden outcome. Human rationale required.', criticalRepeat: boundary ? 2 : 1 },
}));

